package checkout.pricing;

import java.math.BigDecimal;
import java.math.RoundingMode;

public final class DiscountPolicy {
    private static final BigDecimal MEMBER_DISCOUNT = new BigDecimal("0.07");
    private static final BigDecimal BULK_DISCOUNT = new BigDecimal("0.05");

    public static int totalCents(int unitCents, int quantity, boolean member) {
        if (unitCents < 0 || quantity < 0) {
            throw new IllegalArgumentException("unitCents and quantity must be non-negative");
        }
        if (quantity == 0) {
            return 0;
        }

        BigDecimal subtotal = BigDecimal.valueOf(unitCents).multiply(BigDecimal.valueOf(quantity));
        BigDecimal discountRate = BigDecimal.ZERO;
        if (member) {
            discountRate = discountRate.add(MEMBER_DISCOUNT);
        }
        if (quantity >= 12) {
            discountRate = discountRate.add(BULK_DISCOUNT);
        }

        BigDecimal total = subtotal.multiply(BigDecimal.ONE.subtract(discountRate));
        BigDecimal rounded = total.setScale(0, RoundingMode.HALF_EVEN);
        try {
            return rounded.intValueExact();
        } catch (ArithmeticException ex) {
            throw new IllegalArgumentException("total exceeds Integer.MAX_VALUE", ex);
        }
    }
}
